"""Publish the complete official ranking outcome without changing the policy."""

import json
from datetime import datetime
from pathlib import Path
from zoneinfo import ZoneInfo

ROOT = Path(__file__).resolve().parents[2]
report = json.loads((ROOT / "docs/levels-noon-ranked-audit.json").read_text())
if not report["complete"]:
    raise RuntimeError("Do not summarize an incomplete ranking round as complete")
at = datetime.fromisoformat(report["lastCompletedAt"].replace("Z", "+00:00")).astimezone(ZoneInfo("Europe/Helsinki"))
money = lambda n: f"€{n:,.2f}"
percent = lambda n: f"{100*n:.2f}%"
rows = report["summary"]
lines = ["# Levels 1–4: noon ranking outcome", "", f"All twenty authorized ranking weeks completed at {at:%H:%M:%S} Helsinki on14November2026, before the noon cutoff. All used one frozen level-aware policy; there were no replacements or changes in response to ranked results. The user subsequently authorized levels 5–8, starting with 8; see the separate upper-level outcome. No test final or final was entered.", "", f"These positions are the official season{report['season']} snapshot at {report['officialSnapshotAt']}. The leader gaps compare the same five ranked run numbers at each level, not unmatched practice seeds.", "", "| Level | Qualified | Total net profit, five runs | Mean net profit | Aggregate on time | Snapshot rank | Gap to snapshot leader |", "|---|---:|---:|---:|---:|---:|---:|"]
for r in rows:
    lines.append(f"| {r['level']} | {r['qualifiedWeeks']}/5 | {money(r['totalProfitEuros'])} | {money(r['totalProfitEuros']/5)} | {percent(r['onTimeShare'])} | {r['officialRank']} | {money(r['matchedLeaderGapEuros'])} |")
lines += ["", f"Total net profit was {money(sum(r['totalProfitEuros'] for r in rows))} across {sum(r['orders'] for r in rows):,} orders. Undelivered orders: {sum(r['undelivered'] for r in rows)}. Failed visits: {sum(r['failedVisits'] for r in rows)}. Action errors: {sum(r['actionErrors'] for r in rows)}. Recoveries: {sum(r['recoveries'] for r in rows)}. Fines: {money(sum(r['finesEuros'] for r in rows))}.", "", "| Level | Orders | Driver payments | Refunds | Minimum weekly on time |", "|---|---:|---:|---:|---:|"]
for r in rows:
    lines.append(f"| {r['level']} | {r['orders']} | {money(r['driverPaymentsEuros'])} | {money(r['refundsEuros'])} | {percent(r['minimumOnTimeShare'])} |")
lines += ["", "## Decisions before levels 5–8", "", "1. Keep the moderate payment/first-option correction as the recorded lower-level deployment choice. It improved the two-week development comparisons at levels1–3 and all ranked results remain visible here. It is not a statistically promoted universal policy.", "2. Do not transfer the strong0.72payment reduction indiscriminately. It lost profit at levels1–2 even after the option fix. At level3bundling helped, but moderate payment earned more with better timeliness. Driver learning, route formation and supply regime affect the result.", "3. Do not deploy the global portfolio model at lower levels: its conservative cost assumptions excluded too much profitable work. At level8it earned a modest development gain, below the declared promotion screen. Solver correctness does not validate the supplied economics.", "4. The matched ranking gaps remain real. Reliable qualification and improvement over our own control do not establish parity with the leaders. Admission, route opportunities and actual booking-cost response need further level-specific investigation.", "5. The requested pause before levels 5–8 was subsequently lifted by explicit user authorization. The separately frozen upper-level policy retained the level 8 control; the operational failure and incomplete upper submission are recorded in levels-upper-results.md.", "", "## Evidence limits and reproduction", "", "This was an explicitly authorized deadline deployment, not a completed untouched24-pair validation. All earlier experiment outcomes are retained, including unsuccessful models. Five successes at one level provide only a54.93% one-sided95% lower qualification bound under IID-week assumptions; these ranked seeds are not a representative reliability guarantee. Related levels must not be counted as twenty independent weeks.", "", "The audit verifies official world identity and season, the frozen source/configuration, terminal order counts, every ledger total, and the official per-run scores. The retained official snapshot and local artifact hashes support later review. The main validated level8selection and separate prior lower-level candidate were preserved.", "", "Files: [ranking audit](levels-noon-ranked-audit.json), [official snapshot](levels-noon-server.json), [frozen protocol](../experiments/levels-noon-protocol.json), [lower-level research decisions](lower-level-noon-findings.md), [portfolio research](portfolio-development-findings.md).", ""]
(ROOT / "docs/levels-noon-results.md").write_text("\n".join(lines))
